import React from "react";
import { MdEmail, MdPhone, MdDownload, MdSend } from "react-icons/md";
import { contactDetails } from "../Details";
import KaifResume from "../assets/Kaif.CS_resume.pdf";

function Contact() {
  const { email, phone } = contactDetails;
  const whatsappNumber = "6369532396";

  const handleDownloadResume = () => {
    const link = document.createElement('a');
    link.href = KaifResume;
    link.download = "KaifResume.pdf";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleWhatsAppMessage = () => {
    const message = encodeURIComponent("Hi, I would like to connect with you!");
    window.open(`https://wa.me/${whatsappNumber}?text=${message}`, '_blank');
  };

  return (
    <main className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-purple-50 dark:from-slate-900 dark:via-slate-800 dark:to-slate-900 py-16 px-4">
      <div className="container mx-auto max-w-4xl">
        {/* Header Section */}
        <div className="text-center mb-12 animate-fade-in">
          <h1 className="text-4xl md:text-5xl lg:text-6xl font-bold text-slate-800 dark:text-slate-100 mb-4">
            Let's Connect
          </h1>
          <p className="text-lg md:text-xl text-slate-600 dark:text-slate-400 max-w-2xl mx-auto">
            Have a question or want to work together? I'd love to hear from you.
          </p>
        </div>

        {/* Contact Cards Container */}
        <div className="grid md:grid-cols-2 gap-6 mb-8">
          {/* Email Card */}
          <a 
            href={`mailto:${email}`}
            className="group bg-white dark:bg-slate-800 rounded-2xl p-8 shadow-lg hover:shadow-2xl transition-all duration-300 hover:-translate-y-1 border border-slate-200 dark:border-slate-700"
          >
            <div className="flex items-start space-x-4">
              <div className="bg-gradient-to-br from-blue-500 to-blue-600 p-3 rounded-xl group-hover:scale-110 transition-transform duration-300">
                <MdEmail className="w-6 h-6 text-white" />
              </div>
              <div className="flex-1">
                <h3 className="text-sm font-semibold text-slate-500 dark:text-slate-400 mb-2 uppercase tracking-wide">
                  Email Me
                </h3>
                <p className="text-lg md:text-xl font-semibold text-slate-800 dark:text-slate-100 break-all group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">
                  {email}
                </p>
              </div>
            </div>
          </a>

          {/* Phone Card */}
          <a 
            href={`tel:${phone}`}
            className="group bg-white dark:bg-slate-800 rounded-2xl p-8 shadow-lg hover:shadow-2xl transition-all duration-300 hover:-translate-y-1 border border-slate-200 dark:border-slate-700"
          >
            <div className="flex items-start space-x-4">
              <div className="bg-gradient-to-br from-purple-500 to-purple-600 p-3 rounded-xl group-hover:scale-110 transition-transform duration-300">
                <MdPhone className="w-6 h-6 text-white" />
              </div>
              <div className="flex-1">
                <h3 className="text-sm font-semibold text-slate-500 dark:text-slate-400 mb-2 uppercase tracking-wide">
                  Call Me
                </h3>
                <p className="text-lg md:text-xl font-semibold text-slate-800 dark:text-slate-100 group-hover:text-purple-600 dark:group-hover:text-purple-400 transition-colors">
                  {phone}
                </p>
              </div>
            </div>
          </a>
        </div>

        {/* Resume Download Section */}
        <div className="bg-gradient-to-r from-blue-600 to-purple-600 rounded-2xl p-8 md:p-10 shadow-xl text-center">
          <div className="max-w-md mx-auto">
            <h2 className="text-2xl md:text-3xl font-bold text-white mb-3">
              Want to Know More?
            </h2>
            <p className="text-blue-100 mb-6">
              Download my resume to learn about my experience and skills
            </p>
            <button 
              onClick={handleDownloadResume}
              className="group inline-flex items-center space-x-2 bg-white text-blue-600 font-bold py-4 px-8 rounded-xl hover:bg-blue-50 transition-all duration-300 shadow-lg hover:shadow-xl hover:scale-105"
            >
              <MdDownload className="w-5 h-5 group-hover:animate-bounce" />
              <span>Download Resume</span>
            </button>
          </div>
        </div>

        {/* Optional: Quick Message CTA */}
        <div className="mt-8 text-center">
          <p className="text-slate-600 dark:text-slate-400 mb-4">
            Prefer to send a quick message?
          </p>
          <button 
            onClick={handleWhatsAppMessage}
            className="inline-flex items-center space-x-2 text-green-600 dark:text-green-400 font-semibold hover:underline cursor-pointer"
          >
            <MdSend className="w-4 h-4" />
            <span>Send a WhatsApp message</span>
          </button>
        </div>
      </div>
    </main>
  );
}

export default Contact;