import React, { useRef, useEffect, useState } from "react";
import gsap from "gsap";
import { personalDetails } from "../Details";

function Home() {
  const { name, tagline, img } = personalDetails;
  const h11 = useRef();
  const h12 = useRef();
  const h13 = useRef();
  const myimageref = useRef();
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const tl = gsap.timeline();

    tl.from(h11.current, {
      x: "-100%",
      delay: 0.2,
      opacity: 0,
      duration: 1,
      ease: "power3.out",
    })
      .from(
        h12.current,
        {
          x: "-100%",
          opacity: 0,
          duration: 1.1,
          ease: "power3.out",
        },
        "-=0.6"
      )
      .from(
        h13.current,
        {
          x: "-100%",
          opacity: 0,
          duration: 1,
          ease: "power3.out",
        },
        "-=0.7"
      )
      .from(
        myimageref.current,
        {
          x: "150%",
          opacity: 0,
          duration: 1.2,
          ease: "power3.out",
        },
        "-=0.8"
      );
  }, []);

  const handleMouseMove = (e) => {
    const { clientX, clientY } = e;
    setMousePosition({ x: clientX, y: clientY });
  };

  return (
    <main
      className="relative container mx-auto max-width section md:flex justify-between items-center min-h-screen overflow-hidden"
      onMouseMove={handleMouseMove}
    >
      {/* Animated Background */}
      <div className="absolute inset-0 -z-10 overflow-hidden">
        <div
          className="absolute top-20 left-10 w-72 h-72 bg-purple-300 dark:bg-purple-900 rounded-full mix-blend-multiply dark:mix-blend-lighten filter blur-xl opacity-30 animate-blob"
          style={{
            transform: `translate(${mousePosition.x * 0.02}px, ${mousePosition.y * 0.02}px)`,
          }}
        ></div>

        <div
          className="absolute top-40 right-10 w-72 h-72 bg-blue-300 dark:bg-blue-900 rounded-full mix-blend-multiply dark:mix-blend-lighten filter blur-xl opacity-30 animate-blob animation-delay-2000"
          style={{
            transform: `translate(${mousePosition.x * -0.02}px, ${mousePosition.y * -0.02}px)`,
          }}
        ></div>

        <div
          className="absolute -bottom-8 left-1/2 w-72 h-72 bg-pink-300 dark:bg-pink-900 rounded-full mix-blend-multiply dark:mix-blend-lighten filter blur-xl opacity-30 animate-blob animation-delay-4000"
          style={{
            transform: `translate(${mousePosition.x * 0.015}px, ${mousePosition.y * 0.015}px)`,
          }}
        ></div>
      </div>

      {/* Left Content */}
      <div className="flex-1 z-10">
        <div className="inline-block mb-4">
          <span className="px-4 py-2 bg-gradient-to-r from-purple-500/10 to-blue-500/10 dark:from-purple-500/20 dark:to-blue-500/20 backdrop-blur-sm border border-purple-500/20 rounded-full text-sm font-medium text-purple-700 dark:text-purple-300">
            👋 Welcome to my portfolio
          </span>
        </div>

        <h1
          ref={h11}
          className="text-3xl text-dark-heading dark:text-light-heading md:text-5xl xl:text-6xl font-bold mb-4"
        >
          Hi, I'm
        </h1>

        <h1
          ref={h12}
          className="text-4xl md:text-6xl xl:text-7xl font-bold mb-6 bg-clip-text bg-gradient-to-r from-blue-600 via-purple-600 to-pink-600 text-transparent"
        >
          {name}
        </h1>

        <h2
          ref={h13}
          className="text-2xl text-dark-heading/80 dark:text-light-heading/80 md:text-3xl xl:text-4xl font-semibold"
        >
          {tagline}
        </h2>
      </div>

      {/* Right Image */}
      <div className="mt-10 md:mt-0 flex-1 flex justify-center md:justify-end">
        <div className="relative group">
          <div className="absolute -inset-4 bg-gradient-to-r from-blue-600 via-purple-600 to-pink-600 rounded-full opacity-20 blur-2xl group-hover:opacity-30 transition-opacity duration-300"></div>
          <div className="absolute -inset-2 bg-gradient-to-r from-blue-500 to-purple-500 rounded-full opacity-0 group-hover:opacity-20 blur-xl transition-opacity duration-300"></div>

          <div className="relative">
            <img
              ref={myimageref}
              className="w-64 h-64 md:w-80 md:h-80 xl:w-96 xl:h-96 rounded-full object-cover shadow-2xl ring-4 ring-white dark:ring-slate-800 group-hover:scale-105 transition-transform duration-300"
              src={img}
              alt={name}
            />
            <div className="absolute inset-0 rounded-full bg-gradient-to-tr from-blue-600/0 to-purple-600/0 group-hover:from-blue-600/10 group-hover:to-purple-600/10 transition-all duration-300"></div>
          </div>
        </div>
      </div>

      {/* Faster Blob Animation */}
      <style>{`
        @keyframes blob {
          0%, 100% {
            transform: translate(0, 0) scale(1);
          }
          33% {
            transform: translate(20px, -30px) scale(1.05);
          }
          66% {
            transform: translate(-15px, 15px) scale(0.95);
          }
        }
        .animate-blob {
          animation: blob 4s infinite;
        }
        .animation-delay-2000 {
          animation-delay: 1s;
        }
        .animation-delay-4000 {
          animation-delay: 2s;
        }
      `}</style>
    </main>
  );
}

export default Home;
